		i5 = vec4(dot(I5, y_weight * Y), dot(C4, y_weight * Y), dot(A1, y_weight * Y), dot(G0, y_weight * Y));
		h5 = vec4(dot(H5, y_weight * Y), dot(F4, y_weight * Y), dot(B1, y_weight * Y), dot(D0, y_weight * Y));
	}
    f4 = h5.yzwx;

